// Packs models/*.glb into models.js as base64, so the page can load them from a plain file as well as from a server.
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '..', 'models');
const out = {};
for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.glb')).sort()) out[f.slice(0, -4)] = fs.readFileSync(path.join(dir, f)).toString('base64');
fs.writeFileSync(path.join(__dirname, '..', 'models.js'),
  '/* Generated by tools/pack-models.js from models/*.glb. Do not edit. Furniture Kit by Kenney (kenney.nl), CC0. */\nwindow.ROOMLINES_MODELS = ' + JSON.stringify(out) + ';\n');
console.log(`models.js: ${Object.keys(out).length} models`);
